H.background();
const c = P.c, k = Math.max(0, P.k);
// Window must hold the band [c-k, c+k] AND the test point's full sweep, which
// reaches c ± (k+3); also tall enough for f at the sweep's far point.
const reach = k + 3;
const xspan = Math.max(10, Math.abs(c) + reach + 1);
const ymax = Math.max(10, reach + 2);
const v = H.plot2d({ xMin: -xspan, xMax: xspan, yMin: -2, yMax: ymax });
v.grid(); v.axes();
const f = (x) => Math.abs(x - c);
v.fn(f, { color: H.colors.accent, width: 3 });
v.line(-xspan, k, xspan, k, { color: H.colors.violet, width: 2, dash: [6, 5] });
const lo = c - k, hi = c + k;
// shade the solution interval |x - c| <= k on the x-axis
v.line(lo, 0, hi, 0, { color: H.colors.good, width: 8 });
v.dot(lo, 0, { r: 6, fill: H.colors.warn });
v.dot(hi, 0, { r: 6, fill: H.colors.warn });
v.dot(c, 0, { r: 5, fill: H.colors.accent2 });
// animated test point sweeping across the number line
const xs = c + reach * Math.sin(t * 0.7);
const inside = Math.abs(xs - c) <= k;
v.dot(xs, f(xs), { r: 6, fill: inside ? H.colors.good : H.colors.warn });
v.line(xs, 0, xs, f(xs), { color: inside ? H.colors.good : H.colors.warn, width: 1.5, dash: [3, 3] });
v.dot(xs, 0, { r: 5, fill: inside ? H.colors.good : H.colors.warn });
H.text("|x − " + c.toFixed(1) + "|  ≤  " + k.toFixed(1), 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("solution: " + lo.toFixed(1) + " ≤ x ≤ " + hi.toFixed(1) + "    test x = " + xs.toFixed(1) + (inside ? "  ✓ inside" : "  ✗ outside"), 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "|x − c|", color: H.colors.accent }, { label: "level k", color: H.colors.violet }, { label: "solution band", color: H.colors.good }], H.W - 175, 28);
